proc `and`*(a, b: DisplayBrightnessOverrideOptions): DisplayBrightnessOverrideOptions {.borrow.}
proc `not`*(a: DisplayBrightnessOverrideOptions): DisplayBrightnessOverrideOptions {.borrow.}
